import java.util.*;class Solution{public boolean validTree(int n,int[][]e){if(e.length!=n-1)return false;List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int[]x:e){g[x[0]].add(x[1]);g[x[1]].add(x[0]);}boolean[]v=new boolean[n];Deque<Integer>st=new ArrayDeque<>();st.push(0);while(!st.isEmpty()){int u=st.pop();if(v[u])continue;v[u]=true;for(int x:g[u])if(!v[x])st.push(x);}for(boolean x:v)if(!x)return false;return true;}}
